CREATE TABLE IF NOT EXISTS prospects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, region TEXT, business TEXT, sector TEXT, website TEXT, size TEXT, sites TEXT, interest TEXT, areas TEXT, timescale TEXT, budget TEXT, competitors TEXT, source TEXT, source_detail TEXT, contact_name TEXT, contact_title TEXT, contact_email TEXT, contact_phone TEXT, site_address TEXT, billing_address TEXT, notes TEXT, next_step TEXT, next_date TEXT, status TEXT NOT NULL DEFAULT 'new', quote_id INTEGER, held_quote_id INTEGER, project_key TEXT, psc_key TEXT, created_by TEXT, created_name TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT);
CREATE INDEX IF NOT EXISTS idx_prospects_quote ON prospects(quote_id);
CREATE INDEX IF NOT EXISTS idx_prospects_project ON prospects(project_key);
